 const movementHTML=`<div class="analysis-toolbar"><label>Break down change by<select id="movement-dimension"><option value="product">Products</option><option value="line">Lines</option><option value="distributor">Distributors</option></select></label><label>Compare from<select id="movement-year"></select></label><span id="movement-measure"></span></div><p id="movement-context" class="analysis-context"></p><div id="movement-chart" class="wide-chart"></div><p id="movement-note" class="chart-note"></p><details id="movement-unmatched" hidden><summary>Products / groups without comparable detail</summary><div id="movement-unmatched-list"></div></details><details><summary>View contribution numbers</summary><div id="movement-table" class="table-wrap"></div></details>`;
 $('sales').querySelector('.methodology').insertAdjacentHTML('beforebegin',`<section id="view-movement" hidden>${panel('What drove the change?',movementHTML)}</section><section id="view-heatmap" hidden>${panel('Product × month',`<div class="analysis-toolbar"><span id="heatmap-measure"></span><label>Cell measure<select id="heatmap-mode"><option value="achievement">Monthly achievement %</option><option value="ppg">PPG% vs same month last year</option></select></label></div><p id="heatmap-context" class="analysis-context"></p><div id="heatmap-table" class="heatmap-scroll table-wrap"></div><p class="chart-note">Each cell shows its number. — = unknown / unallocated. 0 = reported zero. Click a cell for product details. Achievement colours: &lt;80%, 80–99%, ≥100%. PPG colours: negative, zero, positive.</p>`)}</section><section id="view-lines" hidden>${panel('Line analysis',`<div class="analysis-toolbar"><label>Source line<select id="analysis-line"></select></label><span id="line-analysis-measure"></span></div><p class="chart-note">Source line names are retained separately in each year. Historical lines are never inferred from the current organisation. Product-wide targets are withheld where a product spans lines.</p><div id="line-analysis-kpis" class="mini-kpis"></div><div class="chart-grid">${panel('Products driving the change','<div id="line-movement" class="wide-chart"></div>')}${panel('Monthly performance','<div id="line-monthly" class="wide-chart"></div>')}</div><h3>Products by month</h3><div id="line-heatmap" class="heatmap-scroll table-wrap"></div><div class="panel-title line-table-heading"><h3>Line product detail</h3><button id="line-export">Export Excel</button></div><div id="line-table" class="table-wrap"></div>`)}</section>`);
 $('view-trends').insertAdjacentHTML('beforeend',`<details class="analysis-readiness"><summary>Planning tools & data readiness</summary><div class="chart-grid">${panel('Year-end run-rate scenario','<div id="run-rate"></div>')}${panel('Stock coverage readiness','<div id="stock-readiness"></div>')}</div><p class="chart-note">Price / volume decomposition needs observed, comparable SKU / pack data. IMS market analysis needs a reviewed market definition, pack mapping and separate Monthly / YTD / MAT periods. These analyses stay unavailable until their prerequisites are reviewed; Actual ÷ IMS is not automatically market share.</p></details>`);
 document.body.insertAdjacentHTML('beforeend',`<dialog id="product-drawer" class="product-drawer" aria-labelledby="drawer-title"><div class="drawer-heading"><div><p class="eyebrow">PRODUCT DETAIL</p><h2 id="drawer-title"></h2><p id="drawer-context"></p></div><button id="drawer-close" aria-label="Close product details">Close ×</button></div><div class="analysis-toolbar"><span id="drawer-measure"></span><button id="drawer-focus">Focus dashboard</button><button id="drawer-export">Export Excel</button></div><div id="drawer-kpis" class="mini-kpis"></div><div id="drawer-chart" class="wide-chart"></div><div class="chart-grid">${panel('Distributor mix','<div id="drawer-distributors"></div>')}${panel('Sales-type mix','<div id="drawer-channels"></div>')}</div><h3>Monthly detail</h3><div id="drawer-table" class="table-wrap"></div><p id="drawer-notes" class="chart-note"></p><div class="dialog-tooltip" data-dialog-tooltip role="status"></div></dialog><dialog id="report-dialog" class="report-dialog" aria-labelledby="report-heading"><div class="report-controls"><button id="report-print">Print / Save PDF</button><button id="report-close">Close ×</button></div><div id="meeting-report"></div></dialog>`);
 $('focus-content').querySelector('.focus-table-panel').insertAdjacentHTML('beforebegin',panel('Contribution to change',`<div class="analysis-toolbar"><label>From year<select id="historical-from"></select></label><label>To year<select id="historical-to"></select></label></div><p id="historical-context" class="analysis-context"></p><div id="historical-bridge" class="wide-chart"></div><p id="historical-note" class="chart-note"></p>`,'historical-movement-panel'));
 // Controls are delegated once; no duplicate handlers accumulate on shared refresh.
 document.addEventListener('click',onClick);document.addEventListener('change',onChange);
 $('product-drawer').addEventListener('close',()=>{drawer=null;returnFocus?.focus?.()});
 $('product-drawer').addEventListener('click',ev=>{if(ev.target===$('product-drawer'))$('product-drawer').close()});
 $('save-view').onclick=saveView;$('delete-view').onclick=deleteView;$('share-view').onclick=shareView;$('meeting-open').onclick=openReport;
 $('report-close').onclick=()=>$('report-dialog').close();$('report-print').onclick=()=>{document.body.classList.add('printing-report');window.print()};window.addEventListener('afterprint',()=>document.body.classList.remove('printing-report'));
