 $('drawer-export').onclick=()=>exportTable('Product detail',drawerRows(),drawerColumns(),`Product: ${drawer.product} · ${periodLabel()} · ${scopeText()}`);
 $('line-export').onclick=()=>exportTable('Line product detail',lineRows(),detailColumns(),`Line: ${ui.line} · ${periodLabel()} · ${ui.lineMetric}`);
 $('saved-view').onchange=async()=>{const item=savedViews().find(r=>r.id===$('saved-view').value);$('delete-view').disabled=!item;if(item)await restore(item.config)};
 const actions=document.querySelector('.manager-actions');document.querySelector('main').insertBefore(actions,$('sales'));document.querySelector('main').insertBefore($('manager-status'),$('sales'));
 window.actualDashboard.notify=render;window.actualDashboard.sectionChanged=renderSection;
 if(payload)render();
