function miniCards(cards){return cards.map(([label,value])=>`<div><span>${e(label)}</span><strong>${e(value)}</strong></div>`).join('')}
function monthPairs(metric,filters=dashboard().selection){const d=dashboard();return d.months.map(m=>({name:ms[m-1],current:summary(d.snapshot.year,[m],metric,filters).value,previous:summary(d.snapshot.year-1,[m],metric,filters).value,target:target(selectedProducts(d,filters),metric,[m],false,filters)}))}
function pairedChart(rows,metric,currentYear,previousYear,targets=false){
 if(!rows.length||!rows.some(r=>r.current!=null||r.previous!=null))return '<p class="empty-chart">No comparable amounts for these filters.</p>';
 const values=rows.flatMap(r=>[r.current,r.previous,targets?r.target:null]).filter(Number.isFinite),lo=Math.min(0,...values),hi=Math.max(0,...values),range=hi-lo||1,W=Math.max(650,rows.length*70),L=65,R=W-20,T=35,B=235,Y=v=>B-(v-lo)/range*(B-T),step=(R-L)/rows.length,bw=Math.min(20,step*.26);
 let svg=`<svg style="min-width:${W}px" viewBox="0 0 ${W} 295" role="img" aria-label="${e(metric+' actual '+currentYear+' vs '+previousYear)}">`;
 for(let i=0;i<=4;i++){const v=lo+range*i/4;svg+=`<line x1="${L}" x2="${R}" y1="${Y(v)}" y2="${Y(v)}" stroke="#e4edf5"/><text x="${L-8}" y="${Y(v)+4}" text-anchor="end" font-size="10" fill="#647b92">${short(v)}</text>`}
 rows.forEach((r,i)=>{const x=L+step*(i+.5),tip=`${r.name} · ${currentYear}: ${amt(r.current,metric)} · ${previousYear}: ${amt(r.previous,metric)}${targets?' · Monthly target: '+amt(r.target,metric):''}`;svg+=`<g tabindex="0" data-tip="${e(tip)}" aria-label="${e(tip)}">`;for(const [key,offset,color]of [['previous',-bw-2,'#b8cadd'],['current',2,'#245fa7']]){const v=r[key];if(v!=null)svg+=`<rect x="${x+offset}" y="${Math.min(Y(0),Y(v))}" width="${bw}" height="${Math.max(.7,Math.abs(Y(v)-Y(0)))}" fill="${v<0?'#bd7869':color}"/>`;else svg+=`<text x="${x+offset+bw/2}" y="${Y(0)-8}" text-anchor="middle" font-size="10">—</text>`}if(targets&&r.target!=null)svg+=`<line x1="${x-bw-4}" x2="${x+bw+4}" y1="${Y(r.target)}" y2="${Y(r.target)}" stroke="#c38d3d" stroke-width="2"/>`;svg+=labelLines(r.name,18).slice(0,3).map((text,j)=>`<text x="${x}" y="${B+20+j*13}" text-anchor="middle" font-size="10" fill="#526b83">${e(text)}</text>`).join('')+'</g>'});
 return `<div class="analysis-legend"><span><i class="current-key"></i>${currentYear}</span><span><i class="previous-key"></i>${previousYear}</span>${targets?'<span>— Monthly target</span>':''}</div>`+svg+'</svg>';
}
function pairedRankedChart(rows,metric,currentYear,previousYear){
 rows=rows.slice().sort((a,b)=>(b.current??-Infinity)-(a.current??-Infinity));
 if(!rows.some(r=>r.current!=null||r.previous!=null))return '<p class="empty-chart">No distributor detail available for these periods.</p>';
 const vals=rows.flatMap(r=>[r.current,r.previous]).filter(Number.isFinite),lo=Math.min(0,...vals),hi=Math.max(0,...vals),range=hi-lo||1,L=240,R=650,H=72+rows.length*66,X=v=>L+(v-lo)/range*(R-L),zero=X(0);
 let svg=`<svg viewBox="0 0 940 ${H}" style="min-width:700px" role="img" aria-label="Distributor comparison in ${metric}"><line x1="${zero}" x2="${zero}" y1="20" y2="${H-28}" stroke="#9aafc2"/>`;
 rows.forEach((r,i)=>{const y=40+i*66,tip=`${r.name} · ${currentYear}: ${amt(r.current,metric)} · ${previousYear}: ${amt(r.previous,metric)}`;svg+=`<g tabindex="0" data-tip="${e(tip)}" aria-label="${e(tip)}"><text x="15" y="${y+10}" font-size="12" fill="#35516e">${e(r.name)}</text>`;for(const [key,dy,color]of [['previous',-8,'#b8cadd'],['current',12,'#245fa7']]){const value=r[key];if(value!=null)svg+=`<rect x="${Math.min(zero,X(value))}" y="${y+dy}" width="${Math.max(.7,Math.abs(X(value)-zero))}" height="14" fill="${value<0?'#bc665b':color}"/>`;svg+=`<text x="920" y="${y+dy+11}" text-anchor="end" font-size="11" fill="#35516e">${value==null?'—':n(value)}</text>`}svg+='</g>'});
 for(let i=0;i<=4;i++){const v=lo+range*i/4;svg+=`<text x="${X(v)}" y="${H-5}" text-anchor="middle" font-size="10" fill="#627991">${short(v)}</text>`}
 return `<div class="analysis-legend"><span><i class="previous-key"></i>${previousYear}</span><span><i class="current-key"></i>${currentYear}</span></div><div class="wide-chart">`+svg+'</svg></div>';
}
function rankedHTML(items,metric,click=true){
 if(!items.length)return '<p class="empty-chart">No comparable detail for this selection.</p>';
 const lo=Math.min(0,...items.map(r=>r.value)),hi=Math.max(0,...items.map(r=>r.value)),range=hi-lo||1,L=245,R=670,W=950,H=65+items.length*44,X=v=>L+(v-lo)/range*(R-L),zero=X(0);
 let svg=`<svg class="comparison-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Ranked signed ${metric}"><line x1="${zero}" x2="${zero}" y1="18" y2="${H-28}" stroke="#93a6b8"/>`;
 items.forEach((r,i)=>{const y=40+i*44,tip=`${r.name} · ${amt(r.value,metric)}${r.note?' · '+r.note:''}`;svg+=`<g tabindex="0" ${click?`role="button" data-product-detail="${e(r.name)}"`:''} data-tip="${e(tip)}" aria-label="${e(tip)}"><text x="20" y="${y+4}" font-size="11" fill="#789">${i+1}</text><text x="55" y="${y+4}" font-size="11" fill="#284362">${e(r.name.length>25?r.name.slice(0,24)+'…':r.name)}</text><rect x="${Math.min(zero,X(r.value))}" y="${y-9}" width="${Math.max(.5,Math.abs(X(r.value)-zero))}" height="18" fill="${r.value<0?'#bc665b':'#245fa7'}"/><text x="925" y="${y+4}" text-anchor="end" font-size="11" fill="#284362">${n(r.value)}${r.note?' · '+e(r.note):''}</text></g>`});
 for(let i=0;i<=4;i++){const v=lo+range*i/4;svg+=`<text x="${X(v)}" y="${H-6}" text-anchor="middle" font-size="10" fill="#789">${short(v)}</text>`}return svg+'</svg>';
}
