 const d=dashboard();$('trend').closest('article').querySelector('.progress-legend').hidden=ui.monthlyPY;$('monthly-controls').insertAdjacentHTML('beforeend',buttons('Prior year',[['off','Actual + target'],['on','Add previous year']],ui.monthlyPY?'on':'off','data-monthly-py'));
