 $('leaders-controls').insertAdjacentHTML('beforeend',buttons('Rank by',[['sales','Sales'],['increase','Largest increase'],['decline','Largest decline']],ui.leaderSort,'data-leader-sort'));
 const leaderTitle=$('leaders').closest('article').querySelector('h2'),leaderNote=$('leaders').closest('article').querySelector('.chart-note');leaderTitle.textContent='Leading products';leaderNote.textContent=ui.leaderSort==='sales'?'Shares use the total sales of the selected results, after all filters.':'Ranked by absolute change. PPG compares the same months last year; unavailable baselines are excluded.';
 if(d.selection.product.length===1){leaderTitle.textContent='Selected product · distributor sales';const metric=statesMetric('leaders'),g=new Map();for(const r of scopeRecords(records(),d.selection).filter(r=>r.dataset==='actual'&&r.year===d.snapshot.year&&d.months.includes(r.month))){const x=g.get(r.distributor)||{name:r.distributor,value:0,missing:false};x.missing||=r[metric]==null;x.value+=r[metric]??0;g.set(r.distributor,x)}const denom=summary(d.snapshot.year,d.months,metric,d.selection).value;$('leaders').innerHTML=rankedHTML([...g.values()].filter(x=>!x.missing).map(x=>({...x,note:denom>0?(x.value/denom*100).toFixed(1)+'% of selected':'Share unavailable'})).sort((a,b)=>b.value-a.value),metric,false);leaderNote.textContent='Distributor shares use the selected product sales after all filters; this replaces the one-product ranking.';$('leaders-context').textContent=periodLabel()+' · Product selected; distributor detail replaces the product ranking.'}
 else if(ui.leaderSort!=='sales'){const metric=statesMetric('leaders'),items=selectedProducts().map(p=>{const x=pairs(metric,{...d.selection,product:[p]});return {name:p,value:x.delta,note:pct(x.ppg)+' PPG'}}).filter(r=>r.value!=null&&(ui.leaderSort==='increase'?r.value>0:r.value<0)).sort((a,b)=>ui.leaderSort==='increase'?b.value-a.value:a.value-b.value);$('leaders').innerHTML=rankedHTML(items,metric);$('leaders-context').textContent=`${periodLabel()} vs same months ${d.snapshot.year-1} · Absolute change · Products without a comparable baseline excluded`}
 $('achievements-controls').insertAdjacentHTML('beforeend',buttons('Target variance',[['shortfall','Shortfall only'],['signed','Below & above target']],ui.signedGap?'signed':'shortfall','data-gap-mode'));
 if(ui.signedGap){const metric=statesMetric('achievements'),items=selectedProducts().map(p=>{const value=summary(d.snapshot.year,d.months,metric,{...d.selection,product:[p]}).value,t=target([p],metric);return {name:p,value:value==null||t==null?null:value-t}}).filter(r=>r.value!=null).sort((a,b)=>a.value-b.value);$('achievements').innerHTML=rankedHTML(items,metric);$('achievements-context').textContent='Actual − target · Negative = below target · Positive = above target · '+(d.targetBasis==='annual'?'Full-year':'Period')+' target';}
 $('achievements').closest('article').querySelector('.chart-note').textContent=ui.signedGap?'Signed variance, in the selected measure; no contribution percentages.':'Percentages show each product’s share of the selected total target gap.';
 // Company denominators in Portfolio remain explicit. Detail opens without destroying filters.
