function statesMetric(panel){return document.querySelector(`[data-panel="${panel}"][data-control="metric"].chosen`)?.dataset.choice||'units'}
function buttonProduct(p){return `<button class="product-link" data-product-detail="${e(p)}">${e(p)}</button>`}
function wireDrilldowns(){
 document.querySelectorAll('#leaders [data-focus="product"],#achievements [data-focus="product"],#details [data-focus="product"]').forEach(b=>{b.onclick=()=>openProduct(b.dataset.key,null,b);b.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();b.onclick()}}});
 document.querySelectorAll('#lines-chart [data-focus="line"]').forEach(b=>{b.onclick=()=>{ui.line=b.dataset.key;window.actualDashboard.showSection('lines')};b.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();b.onclick()}}});
 document.querySelectorAll('[data-product-detail]').forEach(b=>b.onkeydown=ev=>{if(b.tagName.toLowerCase()==='g'&&(ev.key==='Enter'||ev.key===' ')){ev.preventDefault();openProduct(b.dataset.productDetail,Number(b.dataset.detailMonth)||null,b)}});
}
function renderAttention(){
 const d=dashboard(),items=[],metric=ui.metric;
 const changes=selectedProducts().map(p=>({product:p,...pairs(metric,{...d.selection,product:[p]})})),decline=changes.filter(x=>x.delta<0).sort((a,b)=>a.delta-b.delta)[0];
 if(decline)items.push({p:decline.product,title:'Largest contribution to decline',text:`${decline.product}: ${amt(decline.delta,metric)} vs same months ${d.snapshot.year-1}.`});
 const gaps=selectedProducts().map(p=>{const actual=summary(d.snapshot.year,d.months,metric,{...d.selection,product:[p]}).value,t=target([p],metric);return {product:p,gap:actual!=null&&t!=null?t-actual:null}}).filter(r=>r.gap>0).sort((a,b)=>b.gap-a.gap);if(gaps[0])items.push({p:gaps[0].product,title:'Largest target shortfall',text:`${gaps[0].product}: ${amt(gaps[0].gap,metric)} remaining against the ${d.targetBasis==='annual'?'full-year':'period'} plan.`});
 const divergent=selectedProducts().map(p=>({product:p,u:pairs('units',{...d.selection,product:[p]}),v:pairs('value',{...d.selection,product:[p]})})).filter(r=>r.u.delta<0&&r.v.delta>0).sort((a,b)=>b.v.delta-a.v.delta)[0];if(divergent)items.push({p:divergent.product,title:'Value up, units down',text:`${divergent.product}: value ${pct(divergent.v.ppg)}, units ${pct(divergent.u.ppg)}. Review price / mix; this does not establish the cause.`});
 const end=Math.max(0,...d.months);if(end>=3&&[end-2,end-1,end].every(m=>d.months.includes(m))){const p=selectedProducts().find(p=>{const vals=[end-2,end-1,end].map(m=>summary(d.snapshot.year,[m],metric,{...d.selection,product:[p]}).value);return vals.every(Number.isFinite)&&vals[0]>vals[1]&&vals[1]>vals[2]});if(p)items.push({p,title:'Three-month downward trend',text:`${p}: declining ${metric} in ${ms[end-3]}, ${ms[end-2]} and ${ms[end-1]}.`})}
 const total=summary(d.snapshot.year,d.months,metric).value;if(total>0){const groups=[...new Set(scopeRecords(records(),d.selection).filter(r=>r.year===d.snapshot.year&&r.dataset==='actual').map(r=>r.distributor))].map(name=>({name,value:summary(d.snapshot.year,d.months,metric,{...d.selection,distributor:[name]}).value})).filter(x=>x.value!=null).sort((a,b)=>b.value-a.value);if(groups[0]?.value/total>=.6)items.push({title:'Distributor concentration ≥60%',text:`${groups[0].name}: ${(groups[0].value/total*100).toFixed(1)}% of selected ${metric}. Check concentration and source coverage.`})}
 $('attention-list').innerHTML=items.slice(0,5).map(r=>`<button class="attention-item" ${r.p?`data-product-detail="${e(r.p)}"`:'data-attention-distributors="1"'}><b>${e(r.title)}</b><span>${e(r.text)}</span><small>Open detail →</small></button>`).join('')||'<p class="chart-note">No rule triggered in the comparable selected data. Incomplete data can prevent a rule being evaluated.</p>';
}
function openProduct(product,month=null,trigger=null){$('tooltip').style.display='none';drawer={product,month,metric:ui.metric};returnFocus=trigger||document.activeElement;renderDrawer();if(!$('product-drawer').open)$('product-drawer').showModal()}
