 $('drawer-chart').innerHTML=pairedChart(chosen.map(m=>({name:ms[m-1],current:summary(d.snapshot.year,[m],metric,f).value,previous:summary(d.snapshot.year-1,[m],metric,f).value,target:target([drawer.product],metric,[m],false,f)})),metric,d.snapshot.year,d.snapshot.year-1,true);
 for(const [key,id]of [['distributor','drawer-distributors'],['channel','drawer-channels']]){const scoped=scopeRecords(records(),f).filter(r=>r.dataset==='actual'&&r.year===d.snapshot.year&&chosen.includes(r.month)),names=[...new Set(scoped.map(r=>r[key]))],items=names.map(name=>{const x=summary(d.snapshot.year,chosen,metric,{...f,[key]:[name]});return {name,value:x.value,note:x.value!=null&&s.value>0?(x.value/s.value*100).toFixed(1)+'% of selected':'Share unavailable'}}).filter(x=>x.value!=null).sort((a,b)=>b.value-a.value);$(id).innerHTML=rankedHTML(items,metric,false)}
 $('drawer-table').innerHTML=table(drawerColumns(),drawerRows().map(row=>row.map((v,i)=>[3,5].includes(i)?v==null?'—':v.toFixed(1)+'%':typeof v==='number'?n(v):e(v))));$('drawer-notes').textContent=`${badge(s)} · V% denominator: full company value for these months, before dimension filters. Monthly chart always uses monthly targets. Source products, pack variants and Tender stay separate. Targets are provisional; a zero target has no achievement percentage. Unallocated targets stay unavailable. ${badge(p)?'Prior period: '+badge(p):''}`;window.actualDashboard.wire();wireDrilldowns();
