function onClick(ev){
 const b=ev.target.closest('button,[role="button"]');if(!b)return;if(b.dataset.page){document.querySelector('.manager-actions').hidden=!['sales','comparison'].includes(b.dataset.page);$('manager-status').hidden=!['sales','comparison'].includes(b.dataset.page);}
 if(b.dataset.productDetail){openProduct(b.dataset.productDetail,Number(b.dataset.detailMonth)||null,b);return}
 let changed=true;
 if(b.dataset.managerMetric)ui.metric=b.dataset.managerMetric;
 else if(b.dataset.heatMetric)ui.heatMetric=b.dataset.heatMetric;
 else if(b.dataset.lineMetric)ui.lineMetric=b.dataset.lineMetric;
 else if(b.dataset.monthlyPy)ui.monthlyPY=b.dataset.monthlyPy==='on';
 else if(b.dataset.distributorView)ui.distributorMode=b.dataset.distributorView;
 else if(b.dataset.leaderSort)ui.leaderSort=b.dataset.leaderSort;
 else if(b.dataset.gapMode)ui.signedGap=b.dataset.gapMode==='signed';
 else if(b.dataset.drawerMetric){if(drawer){drawer.metric=b.dataset.drawerMetric;renderDrawer()}return}
 else if(b.dataset.attentionDistributors){window.actualDashboard.showSection('overview');ui.distributorMode='compare'}
 else changed=false;
 if(changed)window.actualDashboard.render();
}
function onChange(ev){
 const id=ev.target.id;
 if(id==='movement-year')ui.bridgeYear=Number(ev.target.value);
 else if(id==='movement-dimension')ui.bridgeDimension=ev.target.value;
 else if(id==='heatmap-mode')ui.heatMode=ev.target.value;
 else if(id==='analysis-line')ui.line=ev.target.value;
 else if(['historical-from','historical-to'].includes(id)){renderHistoricalBridge();return}
 else if(id==='focus-common-months'){window.comparisonDashboard?.render();return}
 else return;
 window.actualDashboard.render();
}
function capture(){const d=dashboard();return {year:d.snapshot.year,selection:d.selection,months:d.months,periodMode:d.periodMode,targetBasis:d.targetBasis,section:d.section,ui:{...ui},page:!$('comparison').hidden?'comparison':'sales',comparison:window.comparisonDashboard?.capture()}}
function validConfig(config){
 if(!config||typeof config!=='object'||JSON.stringify(config).length>14000)throw Error('Invalid view link.');
 if(!Number.isInteger(config.year)||config.year<2000||config.year>2100)throw Error('Invalid sales year.');
 if(!Array.isArray(config.months)||config.months.length>12||config.months.some(m=>!Number.isInteger(m)||m<1||m>12))throw Error('Invalid months.');
 for(const k of ['product','line','distributor','channel'])if(config.selection?.[k]&&(!Array.isArray(config.selection[k])||config.selection[k].length>150||config.selection[k].some(v=>typeof v!=='string'||v.length>180)))throw Error('Invalid filters.');
 return config;
}
async function restore(config){
 try{validConfig(config);if(!payload||!dashboard()){restorePending=config;return}
 const available=dashboard().snapshot.availableYears;if(!available.includes(config.year)){status(`Year ${config.year} is no longer available. View was not applied.`);return}
 if(config.ui){for(const [key,allowed]of Object.entries({metric:['units','value'],heatMetric:['units','value'],lineMetric:['units','value'],leaderSort:['sales','increase','decline'],bridgeDimension:['product','line','distributor'],heatMode:['achievement','ppg'],distributorMode:['mix','compare']}))if(allowed.includes(config.ui[key]))ui[key]=config.ui[key];for(const key of ['monthlyPY','signedGap'])if(typeof config.ui[key]==='boolean')ui[key]=config.ui[key];if(typeof config.ui.line==='string')ui.line=config.ui.line;}
 await window.actualDashboard.apply(config);if(config.comparison)window.comparisonDashboard?.restore(config.comparison);
 document.querySelector(`[data-page="${config.page==='comparison'?'comparison':'sales'}"]`)?.click();status('View restored. Only available filters were applied; sales data was not changed.');
 }catch(err){status(err.message)}
}
function savedViews(){try{const data=JSON.parse(localStorage.getItem(storageKey)||'[]');return Array.isArray(data)?data.filter(r=>typeof r.id==='string'&&typeof r.name==='string'&&r.config).slice(0,30):[]}catch{return []}}
function refreshSaved(){const rows=savedViews();$('saved-view').innerHTML='<option value="">Saved views…</option>'+rows.map(r=>`<option value="${e(r.id)}">${e(r.name)}</option>`).join('');$('delete-view').disabled=true}
function status(message){$('manager-status').textContent=message}
function saveView(){if(!storageKey)return status('Sign-in context is still loading. Try again.');const name=$('view-name').value.trim();if(!name)return status('Enter a name for this view.');const rows=savedViews(),index=rows.findIndex(r=>r.name===name),item={id:index>=0?rows[index].id:crypto.randomUUID(),name,config:capture()};if(index>=0)rows[index]=item;else rows.push(item);try{localStorage.setItem(storageKey,JSON.stringify(rows.slice(-30)));refreshSaved();$('saved-view').value=item.id;$('delete-view').disabled=false;status('View saved for this account in this browser.')}catch{status('Browser storage is unavailable; the view was not saved.')}}
function deleteView(){try{const id=$('saved-view').value;localStorage.setItem(storageKey,JSON.stringify(savedViews().filter(r=>r.id!==id)));refreshSaved();status('Saved view removed.')}catch{status('Unable to update browser storage.')}}
async function shareView(){const url=new URL(location.href);url.hash='view='+encodeURIComponent(JSON.stringify(capture()));try{await navigator.clipboard.writeText(url.href);status('View link copied. It contains filter choices only; recipients still need approved access.')}catch{status('Clipboard unavailable. Copy the link from the field below.');let input=$('view-link-copy');if(!input){$('manager-status').insertAdjacentHTML('afterend','<input id="view-link-copy" aria-label="View link to copy" readonly>');input=$('view-link-copy')}input.value=url.href;input.select()}}
function readLink(){if(location.hash.startsWith('#view=')){try{restore(validConfig(JSON.parse(decodeURIComponent(location.hash.slice(6)))))}catch{status('The view link is invalid. Current filters were retained.')}}}
function exportTable(title,rows,headers,subtitle){const columns=headers.map((label,i)=>({label,width:i===0?32:24,kind:typeof rows.find(r=>r[i]!=null)?.[i]==='number'?'number':'text'}));const bytes=tableWorkbook({title:'Nerhadou · '+title,subtitle,columns,rows,notes:[`Exported ${new Date().toISOString()} · Data revision ${payload?.revision}. Missing values remain blank.`, 'PPG = (current / previous − 1) × 100; same selected months; positive prior baseline required.','V% uses full company value; line detail shares use selected line sales. Targets are provisional; no distributor/channel allocation is inferred.','Percentage columns contain percentage-point numbers (e.g. 25 means 25%). Estimates are identified in the data status / report.']});const url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})),a=document.createElement('a');a.href=url;a.download='nerhadou-'+title.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-'+dashboard().snapshot.year+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function openReport(){
 const d=dashboard();if(!payload||!d)return;
 const comparison=!$('comparison').hidden;
 const header=`<p class="eyebrow">NERHADOU INTERNATIONAL · COMMERCIAL HUB</p><h1 id="report-heading">${comparison?'Historical comparison':'Performance meeting report'}</h1><p>${e(new Date().toLocaleString())} · Version 32 · Data revision ${payload.revision}</p>`;
 let body;
 if(comparison){const selectors=['focus-context','focus-sales-title','focus-sales-chart','focus-growth-note','focus-growth-chart','focus-trend-chart','historical-context','historical-bridge','focus-table-title','focus-table','focus-table-note'];body=selectors.map(id=>`<div class="report-block">${$(id)?.innerHTML||''}</div>`).join('')+`<p>${e($('focus-data-notes').textContent)}</p>`}
 else {renderMovement();const products=selectedProducts(),rows=products.map(p=>{const f={...d.selection,product:[p]},u=pairs('units',f),v=pairs('value',f),t=target([p],ui.metric),actual=ui.metric==='value'?v.current.value:u.current.value;return [e(p),n(u.current.value),n(v.current.value),pct(u.ppg),pct(v.ppg),n(t),actual!=null&&t>0?n(actual/t*100)+'%':'—']});body=`<p>${e(periodLabel())} · ${e(scopeText())} · Target: ${d.targetBasis==='annual'?'Full year':'Selected period'} · PPG vs same months ${d.snapshot.year-1}</p><div>${$('data-health').innerHTML}</div><div class="kpis">${$('kpis').innerHTML}</div><div class="chart-grid">${panel('Monthly performance',$('trend').innerHTML)}${panel('Contribution to change',$('movement-chart').innerHTML)}</div><h2>Needs attention</h2>${$('attention-list').innerHTML}<h2>Portfolio detail</h2>${table(['Product','Units','Value EGP','Units PPG','Value PPG','Target '+ui.metric,'Achievement'],rows)}<p>Unknown values are shown as —. Target2 is provisional. ${e(badge(summary(d.snapshot.year,d.months,'value')))}</p>`}
 $('meeting-report').innerHTML=header+body;$('report-dialog').showModal();
}
function renderHistoricalBridge(){
 if(!historical)return;const {model,records:rows}=historical,years=model.years,from=$('historical-from').value,to=$('historical-to').value;
 for(const id of ['historical-from','historical-to'])$(id).innerHTML=years.map(y=>`<option value="${y}">${y}</option>`).join('');
 $('historical-from').value=years.includes(Number(from))?from:String(years.at(-2)??years[0]);$('historical-to').value=years.includes(Number(to))?to:String(years.at(-1));
 const a=Number($('historical-from').value),b=Number($('historical-to').value),filters=model.scope==='product'?{product:[model.product]}:{};
 if(a===b||years.length<2){$('historical-bridge').innerHTML='<p class="empty-chart">Choose two different selected years for this bridge.</p>';return}
 const mapped=rows.map(r=>({...r,product:comparisonProduct(r)}));const result=movement(mapped,{a,b,months:model.months,metric:model.metric,dimension:'product',filters});drawBridge('historical-bridge',result,model.metric);$('historical-context').textContent=`${a} → ${b} · ${model.months.map(m=>ms[m-1]).join(', ')||'No common months'} · ${model.metric} · ${model.scope==='product'?model.product:'Company'}${result.estimated?' · Includes estimated value':''}${result.approximate?' · ≈ Approved available totals':''}`;
 $('historical-note').textContent='Bridge uses monthly records for the same months in both years, independently of any separate annual controls. Grey change retains unmatched / missing detail without inventing a zero baseline.';window.actualDashboard?.wire();
}
window.addEventListener('commercial:data',event=>{payload=event.detail;cache.clear();if($('data-health'))window.actualDashboard.render();if(restorePending){const config=restorePending;restorePending=null;restore(config)}});
window.addEventListener('commercial:comparison',event=>{historical=event.detail;if($('historical-bridge'))renderHistoricalBridge()});
mount();
Promise.resolve(window.nerhadouSecurity?.ready).then(me=>{const id=me?.user?.id||me?.user?.email;if(!id)return;storageKey='nerhadou-management-views:'+id;refreshSaved();if(!restored&&payload&&dashboard()){restored=true;readLink()}});
